changeSet.sql:
CREATE UNIQUE INDEX uk_cash_credit_recon_report_lines_active_route
ON itibari.cash_credit_recon_report_lines (report_id, route_public_id)
WHERE deleted = false;

UPDATE itibari.debit_notes
SET delivery_agent_public_id = reference_id
WHERE debit_reference_type = 'DeliveryAgent' AND delivery_agent_public_id IS NULL;

UPDATE itibari.debit_notes
SET delivery_agent_name = (
    SELECT TRIM(CONCAT(COALESCE(agent.first_name, ''), ' ', COALESCE(agent.last_name, '')))
    FROM itibari.delivery_agents agent
    WHERE agent.public_id = itibari.debit_notes.delivery_agent_public_id AND agent.deleted = false
)
WHERE delivery_agent_name IS NULL AND debit_reference_type = 'DeliveryAgent';

UPDATE itibari.debit_notes
SET debt_level = (
    SELECT agent.debt_zone
    FROM itibari.delivery_agents agent
    WHERE agent.public_id = itibari.debit_notes.delivery_agent_public_id AND agent.deleted = false
)
WHERE debt_level IS NULL AND debit_reference_type = 'DeliveryAgent';

UPDATE itibari.debit_notes
SET status = CASE WHEN reconciled = true THEN 'RECONCILED' ELSE 'PENDING' END;

UPDATE itibari.debit_notes
SET route = (
    SELECT recon.delivery_id FROM itibari.reconciliation recon
    WHERE CAST(recon.public_id AS varchar(255)) = itibari.debit_notes.reconciliation_public_id
)
WHERE route IS NULL;

UPDATE itibari.debit_notes
SET route_public_id = (
    SELECT recon.route_id FROM itibari.reconciliation recon
    WHERE CAST(recon.public_id AS varchar(255)) = itibari.debit_notes.reconciliation_public_id
)
WHERE route_public_id IS NULL;

UPDATE itibari.sms_groups
SET default_group = false
WHERE default_group IS NULL;
